import { Component, ComponentInterface, Element, Event, EventEmitter, Fragment, h, Prop } from '@stencil/core';
import { fromEvent, Subject, takeUntil } from 'rxjs';
import { ButtonSize, FilesSelectedEventDetails, FormDataEvent } from '../../types';

/**
 * @slot default - default slot to show the button text, here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 * @slot description - named slot 'description', here is any HTML content allowed, e.g. to show file type or size restrictions.
 */
@Component({
  tag: 'groupui-upload-button',
  styleUrl: 'upload-button.scss',
  shadow: true,
})
export class UploadButton implements ComponentInterface {
  /**
   * sets the size of the button
   */
  @Prop({ reflect: true }) readonly size: ButtonSize = 'm';

  /**
   * disables the upload button
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * defines the file types the file input should accept.
   * See https://www.w3schools.com/TAGS/att_input_accept.asp
   */
  @Prop({ reflect: true }) readonly accept: string;

  /**
   * allows multiple file selection
   */
  @Prop({ reflect: true }) readonly multiple: boolean = false;

  /**
   * name of the upload button element to support forms
   */
  @Prop({ reflect: true }) readonly name: string = 'files';

  /**
   * event emitted when files are selected, the event detail contains the file list of the selected files
   * Format: { acceptedFiles: FileList; rejectedFiles: FileList }
   */
  @Event({ bubbles: false }) groupuiFilesSelected: EventEmitter<FilesSelectedEventDetails>;

  @Element() host: HTMLElement;

  private destroy = new Subject<void>();

  componentDidLoad() {
    this.addClickHandling();

    if (this.form()) {
      this.addFormsHandling();
    }
    this.addFilesSelectedHandling();
  }

  private addFilesSelectedHandling() {
    fromEvent(this.fileInput(), 'change')
      .pipe(takeUntil(this.destroy))
      .subscribe((event: Event) => {
        const files = Array.from((event.target as HTMLInputElement).files);
        this.groupuiFilesSelected.emit({ acceptedFiles: files, rejectedFiles: [] });
      });
  }

  disconnectedCallback() {
    this.destroy.next();
    this.destroy.complete();
  }

  private addClickHandling() {
    fromEvent(this.button(), 'click')
      .pipe(takeUntil(this.destroy))
      .subscribe(() => {
        this.fileInput().click();
      });
  }

  private addFormsHandling() {
    fromEvent(this.form(), 'formdata')
      .pipe(takeUntil(this.destroy))
      .subscribe((event: FormDataEvent) => {
        if (this.name === undefined) return;
        const files = this.fileInput().files;
        if (files) {
          Array.from(files).forEach((file) => {
            event.formData.append(this.name, file);
          });
        }
      });
  }

  private button(): HTMLGroupuiButtonElement {
    return this.host.shadowRoot.querySelector('groupui-button');
  }

  private fileInput(): HTMLInputElement {
    return this.host.shadowRoot.querySelector('input[type="file"]');
  }

  private form(): HTMLFormElement | null {
    return this.host.closest('form');
  }

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  private ariaLabel(): string {
    const label = [];
    if (this.isLabelSlotProvided()) {
      label.push(this.host.querySelector('[slot="label"]')?.textContent);
    }
    label.push(this.getDefaultSlotContent());
    if (this.isDescriptionSlotProvided()) {
      label.push(this.host.querySelector('[slot="description"]')?.textContent);
    }
    return label.join(' ');
  }

  private getDefaultSlotContent(): string {
    let htmlContent = this.host.innerHTML?.trim();
    if (this.isLabelSlotProvided()) {
      htmlContent = this.removeSlotContent(htmlContent, 'label');
    }
    if (this.isDescriptionSlotProvided()) {
      htmlContent = this.removeSlotContent(htmlContent, 'description');
    }
    return htmlContent?.trim();
  }

  private removeSlotContent(content: string, slotName: string): string {
    const start = content.indexOf(this.host.querySelector('[slot="' + slotName + '"]').outerHTML);
    if (start === 0) {
      const end = this.host.querySelector('[slot="' + slotName + '"]').outerHTML.length;
      return content.substring(end);
    } else if (start > 0) {
      return content.substring(0, start);
    }
    return content;
  }

  render() {
    return (
      <Fragment>
        {this.isLabelSlotProvided() && (
          <label id="label" aria-hidden="true">
            <slot name="label" />
          </label>
        )}
        <groupui-button disabled={this.disabled} size={this.size} icon-left="upload-24" aria-label={this.ariaLabel()}>
          <slot></slot>
        </groupui-button>
        {this.isDescriptionSlotProvided() && (
          <div id="description" aria-hidden="true">
            <slot name="description" />
          </div>
        )}
        <input type="file" disabled={this.disabled} accept={this.accept} multiple={this.multiple} name={this.name} />
      </Fragment>
    );
  }
}
